--
-- Name: audit_ti_asset_status_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.audit_ti_asset_status_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF OLD.status IS DISTINCT FROM NEW.status THEN
    VALUES (NEW.id, 'status_change', jsonb_build_object(
      'old_status', OLD.status,
      'new_status', NEW.status,
      'changed_at', now()
    ), NEW.updated_by, now());
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: bc_audit_trigger(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bc_audit_trigger() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_user_id INTEGER;
  v_new_json JSONB;
BEGIN
  v_new_json := to_jsonb(NEW);
  
  -- Extract user ID safely from potential columns
  v_user_id := (v_new_json->>'added_by')::INTEGER;
  
  IF v_user_id IS NULL THEN
    v_user_id := (v_new_json->>'selected_by')::INTEGER;
  END IF;
  
  IF v_user_id IS NULL THEN
    v_user_id := (v_new_json->>'changed_by')::INTEGER;
  END IF;

    business_case_id,
    action,
    entity_type,
    entity_id,
    before_value,
    after_value,
    changed_by
  ) VALUES (
    COALESCE(NEW.business_case_id, OLD.business_case_id),
    TG_OP,
    TG_TABLE_NAME,
    COALESCE(NEW.id, OLD.id),
    row_to_json(OLD),
    row_to_json(NEW),
    v_user_id
  );
  
  RETURN NEW;
END;
$$;


--
-- Name: bs_handle_euphoria_red_flag(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bs_handle_euphoria_red_flag() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.euphoria_panic >= 7 THEN
      opportunity_id,
      buying_influence_id,
      flag_type,
      title,
      description,
      severity,
      status,
      auto_generated,
      created_by,
      updated_by
    )
    SELECT
      NEW.opportunity_id,
      NEW.id,
      'bandera_roja',
      'Euforia/pánico alto',
      CONCAT(
        'La influencia compradora "', NEW.full_name,
        '" registra euforia/pánico ', NEW.euphoria_panic, '/10.'
      ),
      'high',
      'open',
      TRUE,
      NEW.created_by,
      NEW.updated_by
    WHERE NOT EXISTS (
      SELECT 1 FROM opportunity_flag existing
      WHERE existing.buying_influence_id = NEW.id
        AND existing.auto_generated      = TRUE
        AND existing.title               = 'Euforia/pánico alto'
    );
  END IF;
  RETURN NEW;
END;
$$;


