    CONSTRAINT consumable_files_purchase_type_check CHECK ((purchase_type = ANY (ARRAY['public'::text, 'private'::text]))),
    CONSTRAINT consumable_files_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'registered'::text, 'cancelled'::text])))
);


