    CONSTRAINT equipment_purchase_requests_availability_source_check CHECK ((availability_source = ANY (ARRAY['internal'::text, 'supplier'::text]))),
    CONSTRAINT equipment_purchase_requests_availability_status_check CHECK ((availability_status = ANY (ARRAY['not_checked'::text, 'internal_available_ready'::text, 'supplier_requested'::text, 'supplier_confirmed'::text, 'supplier_rejected'::text, 'alternative_required'::text, 'availability_confirmed'::text]))),
    CONSTRAINT equipment_purchase_requests_bc_amortization_months_check CHECK ((bc_amortization_months > 0)),
    CONSTRAINT equipment_purchase_requests_bc_calculation_mode_check CHECK (((bc_calculation_mode)::text = ANY (ARRAY[('monthly'::character varying)::text, ('annual'::character varying)::text]))),
    CONSTRAINT equipment_purchase_requests_bc_duration_years_check CHECK ((bc_duration_years > 0)),
    CONSTRAINT equipment_purchase_requests_bc_equipment_cost_check CHECK ((bc_equipment_cost >= (0)::numeric)),
    CONSTRAINT equipment_purchase_requests_bc_purchase_type_check CHECK (((bc_purchase_type)::text = ANY (ARRAY[('public'::character varying)::text, ('private_comodato'::character varying)::text, ('private_sale'::character varying)::text]))),
    CONSTRAINT equipment_purchase_requests_bc_system_type_check CHECK (((bc_system_type)::text = ANY (ARRAY[('legacy'::character varying)::text, ('modern'::character varying)::text]))),
    CONSTRAINT equipment_purchase_requests_bc_target_margin_percentage_check CHECK (((bc_target_margin_percentage >= (0)::numeric) AND (bc_target_margin_percentage <= (100)::numeric))),
    CONSTRAINT equipment_purchase_requests_participation_decision_check CHECK ((participation_decision = ANY (ARRAY['pending'::text, 'participate'::text, 'not_participate'::text]))),
    CONSTRAINT equipment_purchase_requests_private_modality_check CHECK ((private_modality = ANY (ARRAY['direct_sale'::text, 'rental'::text, 'rental_with_domain_transfer'::text, 'comodato'::text]))),
    CONSTRAINT equipment_purchase_requests_procedure_type_check CHECK (((procedure_type)::text = ANY (ARRAY[('catalogo_electronico'::character varying)::text, ('infima_cuantia'::character varying)::text, ('subasta_inversa_electronica'::character varying)::text, ('menor_cuantia'::character varying)::text, ('cotizacion'::character varying)::text, ('licitacion'::character varying)::text, ('regimen_especial'::character varying)::text]))),
    CONSTRAINT equipment_purchase_requests_purchase_type_check CHECK ((purchase_type = ANY (ARRAY['public'::text, 'private'::text]))),
    CONSTRAINT equipment_purchase_requests_serial_status_check CHECK ((serial_status = ANY (ARRAY['not_applicable_yet'::text, 'pending_reception'::text, 'received_pending_serial'::text, 'serial_registered'::text]))),
    CONSTRAINT equipment_purchase_requests_supply_control_type_check CHECK ((supply_control_type = ANY (ARRAY['bc_maximums'::text, 'commercial_deliverables'::text, 'none'::text, 'pending'::text]))),
    CONSTRAINT equipment_purchase_requests_v2_migration_status_check CHECK ((v2_migration_status = ANY (ARRAY['not_migrated'::text, 'pending'::text, 'migrated'::text, 'error'::text])))
);


