    CONSTRAINT integration_product_map_odoo_product_positive_check CHECK (((odoo_product_id IS NULL) OR (odoo_product_id > 0))),
    CONSTRAINT integration_product_map_reference_check CHECK (((legacy_code IS NOT NULL) OR (spi_sku IS NOT NULL) OR (spi_equipment_model_id IS NOT NULL)))
);


