--
-- Name: opportunity_rating; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.opportunity_rating (
    opportunity_id uuid NOT NULL,
    updated_by integer,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    tiene_presupuesto text DEFAULT 'D'::text NOT NULL,
    tiene_acceso text DEFAULT 'D'::text NOT NULL,
    entiende_proceso_compra text DEFAULT 'D'::text NOT NULL,
    relacion_con_eb text DEFAULT 'D'::text NOT NULL,
    tiene_coach text DEFAULT 'D'::text NOT NULL,
    puntuacion integer GENERATED ALWAYS AS (((((
CASE
    WHEN (tiene_presupuesto = 'S'::text) THEN 20
    ELSE 0
END +
CASE
    WHEN (tiene_acceso = 'S'::text) THEN 20
    ELSE 0
END) +
CASE
    WHEN (entiende_proceso_compra = 'S'::text) THEN 20
    ELSE 0
END) +
CASE
    WHEN (relacion_con_eb = 'S'::text) THEN 20
    ELSE 0
END) +
CASE
    WHEN (tiene_coach = 'S'::text) THEN 20
    ELSE 0
END)) STORED,
    CONSTRAINT opportunity_rating_entiende_proceso_compra_check CHECK ((entiende_proceso_compra = ANY (ARRAY['S'::text, 'N'::text, 'D'::text]))),
    CONSTRAINT opportunity_rating_relacion_con_eb_check CHECK ((relacion_con_eb = ANY (ARRAY['S'::text, 'N'::text, 'D'::text]))),
    CONSTRAINT opportunity_rating_tiene_acceso_check CHECK ((tiene_acceso = ANY (ARRAY['S'::text, 'N'::text, 'D'::text]))),
    CONSTRAINT opportunity_rating_tiene_coach_check CHECK ((tiene_coach = ANY (ARRAY['S'::text, 'N'::text, 'D'::text]))),
    CONSTRAINT opportunity_rating_tiene_presupuesto_check CHECK ((tiene_presupuesto = ANY (ARRAY['S'::text, 'N'::text, 'D'::text])))
);


