-- Name: permisos_estudios_matriculas; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.permisos_estudios_matriculas (
    id bigint NOT NULL,
    user_id integer NOT NULL,
    user_email text NOT NULL,
    institution_name text NOT NULL,
    program_name text,
