    CONSTRAINT permisos_vacaciones_cancellation_status_check CHECK ((cancellation_status = ANY (ARRAY['none'::text, 'pending'::text, 'approved'::text, 'rejected'::text]))),
    CONSTRAINT permisos_vacaciones_check CHECK ((((tipo_solicitud = 'permiso'::text) AND (tipo_permiso = ANY (ARRAY['estudios'::text, 'personal'::text, 'salud'::text, 'calamidad'::text]))) OR (tipo_solicitud = 'vacaciones'::text))),
    CONSTRAINT permisos_vacaciones_escalation_status_check CHECK ((escalation_status = ANY (ARRAY['none'::text, 'reminder_sent'::text, 'escalated'::text]))),
    CONSTRAINT permisos_vacaciones_justificante_status_check CHECK ((justificante_status = ANY (ARRAY['not_required'::text, 'pendiente'::text, 'entregado'::text, 'en_revision'::text, 'observado'::text, 'aceptado'::text, 'rechazado'::text, 'vencido'::text]))),
    CONSTRAINT permisos_vacaciones_recovery_coordination_status_check CHECK ((recovery_coordination_status = ANY (ARRAY['not_required'::text, 'pending_approver_proposal'::text, 'pending_requester_acceptance'::text, 'agreed'::text, 'execution_in_progress'::text, 'pending_verification'::text, 'closed'::text, 'finalized_by_approver'::text]))),
    CONSTRAINT permisos_vacaciones_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'partially_approved'::text, 'pending_final'::text, 'approved'::text, 'rejected'::text, 'cancelled'::text]))),
    CONSTRAINT permisos_vacaciones_subtipo_calamidad_check CHECK ((((tipo_permiso = 'calamidad'::text) AND (subtipo_calamidad IS NOT NULL) AND (length(TRIM(BOTH FROM subtipo_calamidad)) > 0)) OR (tipo_permiso <> 'calamidad'::text))),
    CONSTRAINT permisos_vacaciones_subtipo_salud_check CHECK ((((tipo_permiso = 'salud'::text) AND (subtipo_salud IS NOT NULL) AND (length(TRIM(BOTH FROM subtipo_salud)) > 0)) OR (tipo_permiso <> 'salud'::text))),
    CONSTRAINT permisos_vacaciones_tipo_solicitud_check CHECK ((tipo_solicitud = ANY (ARRAY['permiso'::text, 'vacaciones'::text])))
);


