    id integer NOT NULL,
    purchase_id uuid NOT NULL,
    from_state text NOT NULL,
    to_state text NOT NULL,
    transition_reason text,
    transitioned_by integer,
    metadata jsonb,
    transitioned_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: private_purchase_state_transitions_id_seq; Type: SEQUENCE; Schema: public; Owner: -
--

CREATE SEQUENCE public.private_purchase_state_transitions_id_seq
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


--
-- Name: private_purchase_state_transitions_id_seq; Type: SEQUENCE OWNED BY; Schema: public; Owner: -
--

ALTER SEQUENCE public.private_purchase_state_transitions_id_seq OWNED BY public.private_purchase_state_transitions.id;


--
-- Name: prospect_visits; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.prospect_visits (
    id integer NOT NULL,
    user_email text NOT NULL,
    prospect_name text NOT NULL,
    visit_date date DEFAULT CURRENT_DATE NOT NULL,
    status text NOT NULL,
    check_in_time timestamp with time zone,
    check_out_time timestamp with time zone,
    check_in_lat double precision,
    check_in_lng double precision,
    check_out_lat double precision,
    check_out_lng double precision,
    observations text,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    lead_id uuid,
    is_planned boolean DEFAULT false,
    CONSTRAINT prospect_visits_status_check CHECK ((status = ANY (ARRAY['in_visit'::text, 'visited'::text])))
);


--
-- Name: prospect_visits_id_seq; Type: SEQUENCE; Schema: public; Owner: -
--

CREATE SEQUENCE public.prospect_visits_id_seq
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


--
-- Name: prospect_visits_id_seq; Type: SEQUENCE OWNED BY; Schema: public; Owner: -
--

ALTER SEQUENCE public.prospect_visits_id_seq OWNED BY public.prospect_visits.id;


--
-- Name: public_delivery_plan; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.public_delivery_plan (
    id bigint NOT NULL,
    delivery_ceiling_id bigint NOT NULL,
    status text DEFAULT 'draft'::text NOT NULL,
    notes text,
    created_by integer,
    updated_by integer,
    approved_by integer,
    approved_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT public_delivery_plan_approval_consistency_check CHECK (((status <> 'approved'::text) OR (approved_at IS NOT NULL))),
    CONSTRAINT public_delivery_plan_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'approved'::text, 'cancelled'::text])))
);


--
-- Name: TABLE public_delivery_plan; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.public_delivery_plan IS 'Plan de entregas para compras publicas, asociado a delivery_ceiling.';


