--
-- Name: public_delivery_plan_line; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.public_delivery_plan_line (
    id bigint NOT NULL,
    public_delivery_plan_id bigint NOT NULL,
    delivery_ceiling_line_id bigint NOT NULL,
    scheduled_start date NOT NULL,
    scheduled_end date NOT NULL,
    max_qty_tranche numeric(14,3) NOT NULL,
    notes text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT public_delivery_plan_line_date_range_check CHECK ((scheduled_end >= scheduled_start)),
    CONSTRAINT public_delivery_plan_line_max_qty_positive_check CHECK ((max_qty_tranche > (0)::numeric))
);


--
-- Name: TABLE public_delivery_plan_line; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.public_delivery_plan_line IS 'Tramos de plan por linea de maximo para validaciones de delivery_request.';


