    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    resolved_at timestamp with time zone,
    impact character varying(10) DEFAULT 'medio'::character varying NOT NULL,
    urgency character varying(10) DEFAULT 'medio'::character varying NOT NULL,
