    satisfaction_comment text,
    CONSTRAINT support_tickets_impact_check CHECK (((impact)::text = ANY (ARRAY[('bajo'::character varying)::text, ('medio'::character varying)::text, ('alto'::character varying)::text]))),
    CONSTRAINT support_tickets_priority_check CHECK (((priority)::text = ANY (ARRAY[('baja'::character varying)::text, ('media'::character varying)::text, ('alta'::character varying)::text, ('critica'::character varying)::text]))),
    CONSTRAINT support_tickets_satisfaction_score_check CHECK (((satisfaction_score >= 1) AND (satisfaction_score <= 5))),
    CONSTRAINT support_tickets_status_check CHECK (((status)::text = ANY ((ARRAY['abierto'::character varying, 'triage'::character varying, 'en_progreso'::character varying, 'en_espera'::character varying, 'resuelto'::character varying, 'cerrado'::character varying, 'reabierto'::character varying])::text[]))),
    CONSTRAINT support_tickets_ticket_type_check CHECK (((ticket_type)::text = ANY (ARRAY[('fallo'::character varying)::text, ('implementacion'::character varying)::text, ('requerimiento'::character varying)::text, ('problema'::character varying)::text]))),
    CONSTRAINT support_tickets_urgency_check CHECK (((urgency)::text = ANY (ARRAY[('bajo'::character varying)::text, ('medio'::character varying)::text, ('alto'::character varying)::text])))
);


