    external_signed_by_name text,
    requires_famsign boolean DEFAULT false NOT NULL,
    signature_workflow_id bigint,
    signature_workflow_status text,
    final_verification_token text,
    final_pdf_generated_at timestamp with time zone,
    absent_acta_drive_pdf_id text,
    absent_acta_generated_at timestamp with time zone,
    absent_workflow_id bigint,
    absent_workflow_status text,
    absent_verification_token text,
