    absent_manual_signed_by_user_id integer,
    CONSTRAINT trainings_event_type_check CHECK ((event_type = ANY (ARRAY['capacitacion'::text, 'induccion'::text, 'charla'::text, 'reunion'::text]))),
    CONSTRAINT trainings_modality_check CHECK ((modality = ANY (ARRAY['presencial'::text, 'virtual'::text, 'hibrida'::text]))),
    CONSTRAINT trainings_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'scheduled'::text, 'in_progress'::text, 'completed'::text, 'cancelled'::text]))),
    CONSTRAINT trainings_trainer_type_check CHECK ((trainer_type = ANY (ARRAY['interno'::text, 'externo'::text]))),
    CONSTRAINT trainings_type_check CHECK ((type = ANY (ARRAY['interna'::text, 'externa_instructor'::text, 'externa_desplazamiento'::text])))
);


