-- Name: travel_allowances; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.travel_allowances (
    id bigint NOT NULL,
    source_type character varying(20) NOT NULL,
    source_id bigint,
    requester_email text NOT NULL,
    requester_user_id integer,
    visit_date date NOT NULL,
    city text,
    status character varying(20) DEFAULT 'pending'::character varying NOT NULL,
    amount numeric(12,2) DEFAULT 0 NOT NULL,
    currency character varying(8) DEFAULT 'USD'::character varying NOT NULL,
    finance_user_id integer,
    payment_date date,
    notes text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    trip_type text,
    distance_km numeric(12,2) DEFAULT 0 NOT NULL,
    outside_labor_area boolean DEFAULT false NOT NULL,
    outside_labor_area_reason text,
    fuel_amount numeric(12,2) DEFAULT 0 NOT NULL,
    liquidation_amount numeric(12,2) DEFAULT 0 NOT NULL,
    approved_amount numeric(12,2),
    attendance_check_status character varying(20) DEFAULT 'unchecked'::character varying NOT NULL,
    attendance_check_payload jsonb,
    reviewed_by_user_id integer,
    reviewed_at timestamp with time zone,
    workflow_status character varying(40) DEFAULT 'borrador'::character varying NOT NULL,
    decision_type character varying(40) DEFAULT 'normal_reimbursement'::character varying NOT NULL,
    decision_reason text,
    km_accumulated_month numeric(12,2) DEFAULT 0 NOT NULL,
    km_excess numeric(12,2) DEFAULT 0 NOT NULL,
    reimbursable_amount numeric(12,2) DEFAULT 0 NOT NULL,
    trip_authorized boolean DEFAULT false NOT NULL,
    trip_authorization_ref text,
    trip_reason text,
    total_sri_invoices numeric(12,2) DEFAULT 0,
    total_manual_notes numeric(12,2) DEFAULT 0,
    total_purchases_no_invoice numeric(12,2) DEFAULT 0,
    total_consolidated numeric(12,2) GENERATED ALWAYS AS (((COALESCE(total_sri_invoices, (0)::numeric) + COALESCE(total_manual_notes, (0)::numeric)) + COALESCE(total_purchases_no_invoice, (0)::numeric))) STORED,
    deducible_10_percent numeric(12,2) GENERATED ALWAYS AS (round((((COALESCE(total_sri_invoices, (0)::numeric) + COALESCE(total_manual_notes, (0)::numeric)) + COALESCE(total_purchases_no_invoice, (0)::numeric)) * 0.10), 2)) STORED,
    total_with_card numeric(12,2) DEFAULT 0 NOT NULL,
    total_without_card numeric(12,2) DEFAULT 0 NOT NULL,
    requires_finance_approval boolean DEFAULT false NOT NULL,
    requires_talento_approval boolean DEFAULT false NOT NULL,
    finance_approval_status text DEFAULT 'not_required'::text NOT NULL,
    talento_approval_status text DEFAULT 'not_required'::text NOT NULL,
    finance_approved_by_user_id integer,
    talento_approved_by_user_id integer,
    finance_approved_at timestamp with time zone,
    talento_approved_at timestamp with time zone,
    reviewer_observation text,
    reviewer_observation_at timestamp with time zone,
    reviewer_observation_by integer,
    payment_receipt_drive_url text,
    payment_receipt_drive_id text,
    payment_receipt_uploaded_at timestamp with time zone,
    payment_receipt_uploaded_by integer,
    classification_completed boolean DEFAULT false NOT NULL,
    payment_reference text,
    processing_state character varying(30) DEFAULT 'sin_procesar'::character varying NOT NULL,
    processing_deadline_at timestamp with time zone,
    grace_deadline_at timestamp with time zone,
    processed_month date,
    annulled_at timestamp with time zone,
    annulled_reason text,
    final_balance_amount numeric(12,2) DEFAULT 0 NOT NULL,
    final_balance_result character varying(20) DEFAULT 'en_cero'::character varying NOT NULL,
    CONSTRAINT travel_allowances_attendance_check_status CHECK (((attendance_check_status)::text = ANY (ARRAY[('unchecked'::character varying)::text, ('matched'::character varying)::text, ('review'::character varying)::text, ('mismatch'::character varying)::text, ('no_attendance'::character varying)::text, ('insufficient_geo'::character varying)::text]))),
    CONSTRAINT travel_allowances_final_balance_result_check CHECK (((final_balance_result)::text = ANY ((ARRAY['por_pagar'::character varying, 'en_cero'::character varying, 'por_devolver'::character varying])::text[]))),
    CONSTRAINT travel_allowances_processing_state_check CHECK (((processing_state)::text = ANY ((ARRAY['sin_procesar'::character varying, 'parcial'::character varying, 'liquidado_total'::character varying, 'anulado'::character varying])::text[]))),
    CONSTRAINT travel_allowances_source_type_check CHECK (((source_type)::text = ANY ((ARRAY['client_visit'::character varying, 'prospect_visit'::character varying, 'manual_trip'::character varying, 'operational_exit'::character varying])::text[]))),
    CONSTRAINT travel_allowances_status_check CHECK (((status)::text = ANY (ARRAY[('pending'::character varying)::text, ('approved'::character varying)::text, ('paid'::character varying)::text, ('rejected'::character varying)::text])))
);


