--
-- Name: v_unified_purchase_requests; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_unified_purchase_requests AS
 SELECT (COALESCE((r.id)::text, (epr.id)::text))::integer AS canonical_id,
        CASE
            WHEN (r.id IS NOT NULL) THEN 'v2'::text
            ELSE 'legacy'::text
        END AS store,
    COALESCE((r.payload ->> 'client_name'::text), epr.client_name) AS client_name,
    COALESCE((r.payload ->> 'client_email'::text), epr.client_email) AS client_email,
    COALESCE(((r.payload ->> 'assigned_to'::text))::integer, epr.assigned_to) AS assigned_to,
    COALESCE((r.payload ->> 'assigned_to_email'::text), epr.assigned_to_email) AS assigned_to_email,
    COALESCE((r.payload ->> 'assigned_to_name'::text), epr.assigned_to_name) AS assigned_to_name,
    COALESCE((r.payload ->> 'provider_email'::text), epr.provider_email) AS provider_email,
    COALESCE((r.payload -> 'equipment'::text), to_jsonb(epr.equipment)) AS equipment,
    COALESCE(r.status, epr.status) AS status,
        CASE
            WHEN (r.id IS NOT NULL) THEN 'modern'::text
            ELSE 'legacy'::text
        END AS system_type,
    COALESCE((r.payload ->> 'commercial_certainty'::text), (epr.commercial_certainty)::text) AS commercial_certainty,
    COALESCE((r.payload ->> 'proforma_signed_at'::text), (epr.proforma_signed_at)::text) AS proforma_signed_at,
    COALESCE((r.payload ->> 'proforma_file_id'::text), epr.proforma_file_id) AS proforma_file_id,
    COALESCE((r.payload ->> 'contract_file_id'::text), epr.contract_file_id) AS contract_file_id,
    COALESCE((r.payload ->> 'drive_folder_id'::text), epr.drive_folder_id) AS drive_folder_id,
    COALESCE((r.created_at)::timestamp with time zone, epr.created_at) AS created_at,
    COALESCE((r.updated_at)::timestamp with time zone, epr.updated_at) AS updated_at,
    r.id AS v2_request_id,
    epr.id AS legacy_purchase_id,
    epr.v2_migration_status,
    r.payload AS v2_payload,
    epr.extra AS legacy_extra
   FROM (public.requests r
     FULL JOIN public.equipment_purchase_requests epr ON ((r.id = epr.v2_request_id)))
  WHERE (((r.id IS NULL) OR (r.request_type_id = ( SELECT request_types.id
           FROM public.request_types
          WHERE (request_types.code = 'F.ST-19'::text)))) AND ((epr.id IS NULL) OR (epr.request_type = 'purchase'::text)));


