    CONSTRAINT vacaciones_firmas_signature_hash_check CHECK (((signature_hash_sha256)::text ~ '^[a-f0-9]{64}$'::text)),
    CONSTRAINT vacaciones_firmas_stage_check CHECK ((stage = ANY (ARRAY['solicitud'::text, 'aprobacion_final'::text, 'rechazo'::text])))
);


